dashboard.definition:
{
	"title": "Asset Inventory",
	"description": "Unified device inventory from Catalyst Center, Meraki, IOS, ASA/FTD, ISE, F5, and Windows/AD",
	"inputs": {
		"input_device_type": {
			"options": {
				"defaultValue": [
					"*"
				],
				"items": [
					{
						"label": "All",
						"value": "*"
					},
					{
						"label": "AP",
						"value": "AP"
					},
					{
						"label": "Firewall",
						"value": "Firewall"
					},
					{
						"label": "Gateway",
						"value": "Gateway"
					},
					{
						"label": "Load Balancer",
						"value": "Load Balancer"
					},
					{
						"label": "Network Device",
						"value": "Network Device"
					},
					{
						"label": "Router",
						"value": "Router"
					},
					{
						"label": "Sensor",
						"value": "Sensor"
					},
					{
						"label": "Server",
						"value": "Server"
					},
					{
						"label": "Switch",
						"value": "Switch"
					},
					{
						"label": "WLC",
						"value": "WLC"
					}
				],
				"token": "filter_type"
			},
			"title": "Device Type",
			"type": "input.multiselect"
		},
		"input_mgmt_source": {
			"options": {
				"defaultValue": [
					"*"
				],
				"items": [
					{
						"label": "All",
						"value": "*"
					},
					{
						"label": "Catalyst Center",
						"value": "Catalyst Center"
					},
					{
						"label": "Meraki Dashboard",
						"value": "Meraki Dashboard"
					},
					{
						"label": "IOS Syslog",
						"value": "IOS Syslog"
					},
					{
						"label": "Firewall Syslog",
						"value": "Firewall Syslog"
					},
					{
						"label": "ISE NAD",
						"value": "ISE NAD"
					},
					{
						"label": "F5 iControl",
						"value": "F5 iControl"
					},
					{
						"label": "Windows/AD",
						"value": "Windows/AD"
					}
				],
				"token": "filter_source"
			},
			"title": "Management Source",
			"type": "input.multiselect"
		},
		"input_time_range": {
			"options": {
				"defaultValue": "-4h@m,now",
				"token": "time_tok"
			},
			"title": "Time Selector",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "-24h@h",
						"latest": "now"
					}
				}
			}
		},
		"tokens": {
			"default": {}
		}
	},
	"visualizations": {
		"viz_about_bg": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_gap_analysis": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_gap_fw": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_gap_kpi": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_inv_charts": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_inv_kpi": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_inv_location": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_inv_table": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_by_family": {
			"dataSources": {
				"primary": "ds_count_by_family"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"xAxisVisibility": "show",
				"yAxisVisibility": "show"
			},
			"title": "Devices by Family",
			"type": "splunk.bar"
		},
		"viz_by_location": {
			"dataSources": {
				"primary": "ds_count_by_location"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"xAxisVisibility": "show",
				"yAxisVisibility": "show"
			},
			"title": "Devices by Location",
			"type": "splunk.bar"
		},
		"viz_by_source": {
			"dataSources": {
				"primary": "ds_filtered_count_by_source"
			},
			"options": {
				"backgroundColor": "transparent",
				"showDonutHole": true
			},
			"title": "Devices by Management Source",
			"type": "splunk.pie"
		},
		"viz_by_type": {
			"dataSources": {
				"primary": "ds_filtered_count_by_type"
			},
			"options": {
				"backgroundColor": "transparent",
				"showDonutHole": true
			},
			"title": "Devices by Type",
			"type": "splunk.pie"
		},
		"viz_firewall_gap_table": {
			"dataSources": {
				"primary": "ds_firewall_gap"
			},
			"description": "All known firewalls — which are sending FTD/ASA/eStreamer data to Splunk",
			"options": {
				"backgroundColor": "transparent",
				"count": 20,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				},
				"fontSize": "small",
				"columnFormat": {
					"data_status": {
						"rowBackgroundColors": "> table | seriesByName(\"data_status\") | matchValue(viz_firewall_gap_table_datastatus_colors)"
					}
				}
			},
			"title": "Firewall Data Status",
			"type": "splunk.table",
			"context": {
				"viz_firewall_gap_table_datastatus_colors": [
					{
						"match": "missing",
						"value": "rgba(214,69,80,0.35)"
					},
					{
						"match": "Missing",
						"value": "rgba(214,69,80,0.35)"
					},
					{
						"match": "No data",
						"value": "rgba(214,69,80,0.35)"
					},
					{
						"match": "NO DATA",
						"value": "rgba(214,69,80,0.35)"
					},
					{
						"match": "absent",
						"value": "rgba(214,69,80,0.35)"
					},
					{
						"match": "present",
						"value": "rgba(110,190,74,0.15)"
					},
					{
						"match": "Present",
						"value": "rgba(110,190,74,0.15)"
					},
					{
						"match": "OK",
						"value": "rgba(110,190,74,0.15)"
					}
				]
			}
		},
		"viz_fw_header": {
			"options": {
				"fontColor": "#E5A823",
				"fontSize": "small",
				"markdown": "### Firewall Coverage"
			},
			"type": "splunk.markdown"
		},
		"viz_fw_kpi_expected": {
			"dataSources": {
				"primary": "ds_fw_kpi_expected"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#049FD9",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "FW Expected",
			"type": "splunk.singlevalue",
			"description": "Total firewalls expected based on inventory records"
		},
		"viz_fw_kpi_gap": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 1,
						"value": "#6EBE4A"
					},
					{
						"from": 1,
						"to": 5,
						"value": "#E5A823"
					},
					{
						"from": 5,
						"value": "#D64550"
					}
				]
			},
			"dataSources": {
				"primary": "ds_fw_kpi_gap"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "FW Missing",
			"type": "splunk.singlevalue",
			"description": "Firewalls in inventory with no data in Splunk"
		},
		"viz_fw_kpi_pairs": {
			"dataSources": {
				"primary": "ds_fw_kpi_pairs"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#049FD9",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "HA Pairs Detected",
			"type": "splunk.singlevalue",
			"description": "Estimated firewall high-availability pairs detected"
		},
		"viz_fw_kpi_sending": {
			"dataSources": {
				"primary": "ds_fw_kpi_sending"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#6EBE4A",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "FW Sending Data",
			"type": "splunk.singlevalue",
			"description": "Firewalls actively sending syslog or event data"
		},
		"viz_gap_header_bg": {
			"options": {
				"fillColor": "rgba(255,255,255,0.88)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.06)"
			},
			"type": "splunk.rectangle"
		},
		"viz_gap_kpi_nodata": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 1,
						"value": "#6EBE4A"
					},
					{
						"from": 1,
						"to": 10,
						"value": "#E5A823"
					},
					{
						"from": 10,
						"value": "#D64550"
					}
				]
			},
			"dataSources": {
				"primary": "ds_gap_kpi_nodata"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "No Data",
			"type": "splunk.singlevalue",
			"description": "Devices with no data received in the time range"
		},
		"viz_gap_kpi_pct": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 50,
						"value": "#D64550"
					},
					{
						"from": 50,
						"to": 80,
						"value": "#E5A823"
					},
					{
						"from": 80,
						"value": "#6EBE4A"
					}
				]
			},
			"dataSources": {
				"primary": "ds_gap_kpi_pct"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"unit": "%",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "Coverage",
			"type": "splunk.singlevalue",
			"description": "Percentage of inventory devices sending data"
		},
		"viz_gap_kpi_sending": {
			"dataSources": {
				"primary": "ds_gap_kpi_sending"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#6EBE4A",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "Sending Data",
			"type": "splunk.singlevalue",
			"description": "Devices actively sending telemetry or log data"
		},
		"viz_gap_kpi_total": {
			"dataSources": {
				"primary": "ds_gap_kpi_total"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#049FD9",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "Total Devices",
			"type": "splunk.singlevalue",
			"description": "Total devices evaluated for data coverage"
		},
		"viz_gap_nodata_table": {
			"dataSources": {
				"primary": "ds_gap_no_data"
			},
			"description": "These inventory devices have no matching events in any Splunk data source",
			"options": {
				"backgroundColor": "transparent",
				"count": 20,
				"fontSize": "small",
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				},
				"showRowNumbers": true
			},
			"title": "Devices NOT Sending Data to Splunk",
			"type": "splunk.table"
		},
		"viz_gap_section": {
			"options": {
				"fillColor": "rgba(255,255,255,0.45)",
				"rx": 12,
				"strokeColor": "rgba(0,0,0,0.06)"
			},
			"type": "splunk.rectangle"
		},
		"viz_gap_summary_bar": {
			"dataSources": {
				"primary": "ds_gap_summary"
			},
			"description": "Sending Data vs No Data per device family",
			"options": {
				"backgroundColor": "transparent",
				"dataValuesDisplay": "all",
				"seriesColors": [
					"#D64550",
					"#6EBE4A"
				],
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"title": "Coverage by Device Family",
			"type": "splunk.bar"
		},
		"viz_header_bg": {
			"options": {
				"fillColor": "rgba(255,255,255,0.88)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.06)"
			},
			"type": "splunk.rectangle"
		},
		"viz_info_charts": {
			"options": {
				"fontColor": "#2B2B2B",
				"fontSize": "small",
				"markdown": "### Metric Reference — Asset Inventory\n\n---\n\n**Total Devices** — Unique devices across all management sources\n\n**Known IP Addresses** — Devices with a known management IP\n\n**Known Serials** — Devices with a hardware serial number\n\n**Last Lookup Refresh** — Scheduled nightly at 02:05 AM\n\n---\n\n**Devices by Type** — Pie chart of device categories (switch, router, AP, firewall, etc.)\n\n**Devices by Management Source** — Which platform discovered each device\n\n**Devices by Family** — Hardware families (Catalyst 9300, Meraki MR, ASA 5500, etc.)\n\n**Devices by Location** — Device distribution across physical sites\n\n---\n\n**Full Inventory** — Searchable table with device name, type, IP, serial, site, source, and last-seen time"
			},
			"type": "splunk.markdown"
		},
		"viz_info_gap": {
			"options": {
				"fontColor": "#2B2B2B",
				"fontSize": "small",
				"markdown": "### Metric Reference — Data Coverage Gaps\n\n---\n\n**Total Devices** — Catalyst Center managed devices in the asset inventory\n\n**Sending Data** — Devices with live telemetry arriving in Splunk within the selected time range\n\n**No Data** — Devices that have never sent any data to Splunk\n\n**Coverage** — Percentage of managed devices with active data\n\n---\n\n**Coverage by Device Family** — Data coverage broken down by hardware family\n\n**Devices NOT Sending Data** — Detail table with first seen, last seen, and data status (Sending Data / Data Stopped / NO DATA)\n\n---\n\n**FW Sending Data** — Firewalls actively sending FTD/ASA/eStreamer data\n\n**FW Expected** — Expected firewall count from the asset inventory\n\n**FW Missing** — Gap between expected and sending firewalls\n\n**HA Pairs Detected** — High availability pair discovery\n\n**Firewall Data Status** — Per-firewall detail with sourcetypes, event count, first seen, and last seen"
			},
			"type": "splunk.markdown"
		},
		"viz_inv_section": {
			"options": {
				"fillColor": "rgba(255,255,255,0.45)",
				"rx": 12,
				"strokeColor": "rgba(0,0,0,0.06)"
			},
			"type": "splunk.rectangle"
		},
		"viz_inventory_table": {
			"dataSources": {
				"primary": "ds_inventory_table"
			},
			"description": "Device Inventory Detail",
			"options": {
				"backgroundColor": "transparent",
				"columnOrder": [
					"Device Name",
					"Type",
					"Family",
					"Platform",
					"IP Address",
					"Software",
					"Serial",
					"Location",
					"Source",
					"Health",
					"Compliance",
					"Last Seen"
				],
				"count": 50,
				"fontSize": "small",
				"headerVisibility": "fixed",
				"tableFormat": {
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)",
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)"
				}
			},
			"title": "Full Inventory",
			"type": "splunk.table"
		},
		"viz_last_refresh": {
			"dataSources": {
				"primary": "ds_last_refresh"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#2B2B2B",
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "Last Lookup Refresh",
			"type": "splunk.singlevalue",
			"description": "Most recent inventory lookup refresh timestamp"
		},
		"viz_p_hdr_bg": {
			"options": {
				"fillColor": "rgba(255,255,255,0.88)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.06)"
			},
			"type": "splunk.rectangle"
		},
		"viz_p_hdr_title": {
			"options": {
				"fontColor": "#005073",
				"markdown": "## Asset Inventory",
				"fontSize": "large"
			},
			"type": "splunk.markdown"
		},
		"viz_total_devices": {
			"dataSources": {
				"primary": "ds_total_devices"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#2B2B2B",
				"sparklineDisplay": "off",
				"unit": "devices",
				"unitPosition": "after",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "Total Devices",
			"type": "splunk.singlevalue",
			"description": "Total unique devices in the consolidated asset inventory"
		},
		"viz_total_with_ip": {
			"dataSources": {
				"primary": "ds_total_with_ip"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#2B2B2B",
				"sparklineDisplay": "off",
				"unit": "with IP",
				"unitPosition": "after",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "Known IP Addresses",
			"type": "splunk.singlevalue",
			"description": "Devices with a known IP address in inventory"
		},
		"viz_total_with_serial": {
			"dataSources": {
				"primary": "ds_total_with_serial"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#2B2B2B",
				"sparklineDisplay": "off",
				"unit": "with serial",
				"unitPosition": "after",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "Known Serials",
			"type": "splunk.singlevalue",
			"description": "Devices with a serial number recorded in inventory"
		},
		"viz_narr_inventory": {
			"type": "splunk.markdown",
			"options": {
				"markdown": "Centralized view of **all Cisco network assets** discovered across Catalyst Center, Meraki, and other management platforms. Use this tab to verify device coverage, spot missing serial numbers, and drill into the inventory by type, source, or location."
			}
		},
		"viz_narr_gaps": {
			"type": "splunk.markdown",
			"options": {
				"markdown": "Identifies **devices in inventory that are not sending data** to Splunk — helping you close visibility gaps before they become blind spots. The firewall section highlights missing ASA, FTD, and Firepower data sources."
			}
		},
		"viz_about_purpose": {
			"type": "splunk.markdown",
			"options": {
				"markdown": "## Asset Inventory & Coverage Dashboard\n\nThis dashboard provides a **consolidated view of all Cisco network assets** discovered across management platforms (Catalyst Center, Meraki Dashboard, and other sources), along with a **data coverage gap analysis** that identifies devices not actively sending telemetry or log data to Splunk.\n\n**Audience:** Network operations, security operations, IT asset management\n\n**Data Sources:** asset_inventory lookup (generated from Catalyst Center, Meraki, and other management APIs), Cisco syslog/NetFlow data in Splunk indexes\n\n**Refresh:** Data updates when the inventory lookup is refreshed (nightly at 02:05 AM); coverage gaps are evaluated against the selected time range\n\n---\n\n### Tab Guide\n\n**Asset Inventory** — Browse and filter the full device inventory by type, management source, and device family. View breakdowns by location and platform.\n\n**Data Coverage Gaps** — Identify devices that exist in inventory but are not sending any data to Splunk. Includes a dedicated firewall coverage section for ASA/FTD/Firepower devices.\n\n**About** — This page. Metric reference, data sources, and troubleshooting."
			}
		},
		"viz_about_sources": {
			"type": "splunk.markdown",
			"options": {
				"markdown": "### Data Sources & Troubleshooting\n\n**Primary Lookup:** asset_inventory — consolidated from Catalyst Center device health, Meraki device inventory, and other management platform APIs. Refreshed nightly at 02:05 AM.\n\n**Coverage Evaluation:** Searches Splunk indexes for matching device events to determine whether each inventory device is actively sending data.\n\n**Firewall Detection:** Pattern-matches device family against ASA, FTD, and Firepower strings to build the dedicated firewall coverage analysis.\n\n---\n\n**No devices appearing?**\nVerify the asset_inventory lookup exists and is populated. Run: | inputlookup asset_inventory | stats count\n\n**Coverage % seems wrong?**\nCoverage is evaluated over the selected time range. A narrow window may miss devices that report infrequently. Try expanding to 24h or 7d.\n\n**Firewall section empty?**\nThe firewall section filters on device_family matching ASA, FTD, or Firepower. If your inventory uses different naming, the regex may need adjustment."
			}
		}
	},
	"dataSources": {
		"ds_count_by_family": {
			"name": "Devices by Family",
			"options": {
				"extend": "ds_inventory_base",
				"query": "| stats count by device_family"
			},
			"type": "ds.chain"
		},
		"ds_count_by_location": {
			"name": "Devices by Location",
			"options": {
				"extend": "ds_inventory_base",
				"query": "| where len(location)>0 \n| stats count by location"
			},
			"type": "ds.chain"
		},
		"ds_filtered_count_by_source": {
			"name": "Devices by Management Source",
			"options": {
				"extend": "ds_inventory_base",
				"query": "| stats count by management_source"
			},
			"type": "ds.chain"
		},
		"ds_filtered_count_by_type": {
			"name": "Devices by Type",
			"options": {
				"extend": "ds_inventory_base",
				"query": "| stats count by device_type"
			},
			"type": "ds.chain"
		},
		"ds_firewall_gap": {
			"name": "Firewall Gap Detail",
			"options": {
				"extend": "ds_gap_analysis",
				"query": "| where match(device_family, \"(?i)ASA|FTD|Firepower\") \n| table device_name, device_family, location, ip_address, management_source, data_status \n| sort data_status, device_name"
			},
			"type": "ds.chain"
		},
		"ds_firewall_kpis": {
			"name": "Firewall KPIs Base",
			"options": {
				"extend": "ds_gap_analysis",
				"query": "| where match(device_family, \"(?i)ASA|FTD|Firepower\") \n| stats count as expected, sum(eval(if(data_status==\"Sending Data\",1,0))) as fw_sending \n| eval gap=expected-fw_sending, ha_pairs=round(fw_sending/2, 2), gap_pct=if(expected>0, round(gap/expected*100,1), 0) \n| fields fw_sending, expected, gap, ha_pairs, gap_pct"
			},
			"type": "ds.chain"
		},
		"ds_fw_kpi_expected": {
			"name": "FW Expected",
			"options": {
				"extend": "ds_firewall_kpis",
				"query": "| fields expected"
			},
			"type": "ds.chain"
		},
		"ds_fw_kpi_gap": {
			"name": "FW Missing",
			"options": {
				"extend": "ds_firewall_kpis",
				"query": "| fields gap"
			},
			"type": "ds.chain"
		},
		"ds_fw_kpi_pairs": {
			"name": "HA Pairs Detected",
			"options": {
				"extend": "ds_firewall_kpis",
				"query": "| fields ha_pairs"
			},
			"type": "ds.chain"
		},
		"ds_fw_kpi_sending": {
			"name": "FW Sending Data",
			"options": {
				"extend": "ds_firewall_kpis",
				"query": "| fields fw_sending"
			},
			"type": "ds.chain"
		},
		"ds_gap_analysis": {
			"name": "Asset Inventory - ds_gap_analysis",
			"options": {
				"query": "| inputlookup asset_inventory\n| eval short_name=device_name_short, ip=ip_address\n| append\n[| search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\"\n| stats count by DeviceName, IpAddress\n| eval splunk_host=lower(DeviceName),\nsplunk_short=lower(mvindex(split(DeviceName,\".\"),0)),\nsplunk_ip=IpAddress, has_data=1\n| fields splunk_host, splunk_short, splunk_ip, has_data]\n| append\n[| search `index_network` sourcetype=\"cisco:ios\"\n| stats count by host\n| eval splunk_host=lower(host),\nsplunk_short=lower(mvindex(split(host,\".\"),0)),\nhas_data=1\n| fields splunk_host, splunk_short, has_data]\n| append\n[| tstats `scd_summariesonly` count from datamodel=Network_Traffic by All_Traffic.dvc\n| rename \"All_Traffic.dvc\" as dvc\n| eval splunk_host=lower(dvc),\nsplunk_short=lower(mvindex(split(dvc,\".\"),0)),\nhas_data=1\n| where isnotnull(splunk_host) AND splunk_host!=\"\"\nAND NOT match(splunk_host, \"^[0-9a-f]{8}-[0-9a-f]{4}-\")\n| fields splunk_host, splunk_short, has_data]\n| append\n[| search `index_identity` sourcetype=\"cisco:ise:syslog\"\n| rex \"NetworkDeviceName=(?<nad_name>[^,]+)\"\n| where isnotnull(nad_name) AND nad_name!=\"DefaultNetworkDevice\"\n| stats count by nad_name\n| eval splunk_host=lower(nad_name),\nsplunk_short=lower(mvindex(split(nad_name,\".\"),0)),\nhas_data=1\n| fields splunk_host, splunk_short, has_data]\n| append\n[| search `index_windows` (sourcetype=\"*WinEventLog\" OR sourcetype=\"ActiveDirectory\" OR sourcetype=\"MSAD:NT6:DNS\")\n| stats count by host\n| eval splunk_host=lower(host),\nsplunk_short=lower(mvindex(split(host,\".\"),0)),\nhas_data=1\n| fields splunk_host, splunk_short, has_data]\n| append\n[| search `index_dhcp` sourcetype=\"DhcpSrvLog\"\n| stats count by host\n| eval splunk_host=lower(host),\nsplunk_short=lower(mvindex(split(host,\".\"),0)),\nhas_data=1\n| fields splunk_host, splunk_short, has_data]\n| eventstats values(eval(if(has_data==1, splunk_host, null()))) as all_splunk_hosts,\nvalues(eval(if(has_data==1, splunk_short, null()))) as all_splunk_shorts,\nvalues(eval(if(has_data==1, splunk_ip, null()))) as all_splunk_ips\n| where isnotnull(device_name)\n| eval matched=if(\n(short_name IN (all_splunk_hosts))\nOR (short_name IN (all_splunk_shorts))\nOR (ip IN (all_splunk_ips))\nOR (ip IN (all_splunk_hosts))\nOR (lower(device_name) IN (all_splunk_hosts))\nOR (lower(device_name) IN (all_splunk_shorts))\n, 1, 0)\n| eval data_status=if(matched==1, \"Sending Data\", \"NO DATA\")\n| table device_name, device_family, device_role, platform_id, location, ip_address, health_score, management_source, data_status\n| sort data_status, device_family, location, device_name",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_gap_kpi_nodata": {
			"name": "No Data",
			"options": {
				"extend": "ds_gap_kpis",
				"query": "| fields no_data"
			},
			"type": "ds.chain"
		},
		"ds_gap_kpi_pct": {
			"name": "Coverage",
			"options": {
				"extend": "ds_gap_kpis",
				"query": "| fields coverage_pct"
			},
			"type": "ds.chain"
		},
		"ds_gap_kpi_sending": {
			"name": "Sending Data",
			"options": {
				"extend": "ds_gap_kpis",
				"query": "| fields sending"
			},
			"type": "ds.chain"
		},
		"ds_gap_kpi_total": {
			"name": "Gap Total Devices",
			"options": {
				"extend": "ds_gap_kpis",
				"query": "| fields total"
			},
			"type": "ds.chain"
		},
		"ds_gap_kpis": {
			"name": "Gap KPIs Base",
			"options": {
				"extend": "ds_gap_analysis",
				"query": "| stats count as total, sum(eval(if(data_status==\"Sending Data\",1,0))) as sending \n| eval no_data=total-sending, coverage_pct=round(sending/total*100,1) \n| fields total, sending, no_data, coverage_pct"
			},
			"type": "ds.chain"
		},
		"ds_gap_no_data": {
			"name": "Devices NOT Sending Data",
			"options": {
				"extend": "ds_gap_analysis",
				"query": "| where data_status=\"NO DATA\" \n| table device_name, device_family, device_role, platform_id, location, ip_address, management_source, health_score"
			},
			"type": "ds.chain"
		},
		"ds_gap_summary": {
			"name": "Gap Summary by Family",
			"options": {
				"extend": "ds_gap_analysis",
				"query": "| stats count by device_family, data_status \n| rename data_status as status"
			},
			"type": "ds.chain"
		},
		"ds_inventory_base": {
			"name": "Inventory Base",
			"options": {
				"extend": "ds_lookup_base",
				"query": "| eval _filter_type=if(\"$filter_type$\"=\"*\",1,if(like(\"$filter_type$\",\"%\".device_type.\"%\"),1,0)), _filter_src=if(\"$filter_source$\"=\"*\",1,if(like(\"$filter_source$\",\"%\".management_source.\"%\") OR like(management_source,\"%\".\"$filter_source$\".\"%\"),1,0)) \n| where _filter_type=1 AND _filter_src=1 \n| fields - _filter_type _filter_src"
			},
			"type": "ds.chain"
		},
		"ds_inventory_table": {
			"name": "Full Inventory",
			"options": {
				"extend": "ds_inventory_base",
				"query": "| sort device_type device_name \n| rename device_name as \"Device Name\", device_name_short as \"Short Name\", device_type as \"Type\", device_family as \"Family\", platform_id as \"Platform\", ip_address as \"IP Address\", mac_address as \"MAC Address\", software_version as \"Software\", serial_number as \"Serial\", location as \"Location\", device_role as \"Role\", device_series as \"Series\", health_score as \"Health\", compliance_status as \"Compliance\", management_source as \"Source\", last_seen as \"Last Seen\""
			},
			"type": "ds.chain"
		},
		"ds_last_refresh": {
			"name": "Last Lookup Refresh",
			"options": {
				"extend": "ds_lookup_base",
				"query": "| stats max(last_seen) as last_refresh"
			},
			"type": "ds.chain"
		},
		"ds_lookup_base": {
			"name": "Lookup Base",
			"options": {
				"query": "| inputlookup asset_inventory\n| fields device_name, device_name_short, device_type, device_family, device_role, device_series, platform_id, ip_address, mac_address, software_version, serial_number, location, health_score, compliance_status, management_source, last_seen",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_total_devices": {
			"name": "Total Devices",
			"options": {
				"extend": "ds_lookup_base",
				"query": "| stats count as total"
			},
			"type": "ds.chain"
		},
		"ds_total_with_ip": {
			"name": "Known IP Addresses",
			"options": {
				"extend": "ds_lookup_base",
				"query": "| where len(ip_address)>0 \n| stats count as total"
			},
			"type": "ds.chain"
		},
		"ds_total_with_serial": {
			"name": "Known Serials",
			"options": {
				"extend": "ds_lookup_base",
				"query": "| where len(serial_number)>0 \n| stats count as total"
			},
			"type": "ds.chain"
		}
	},
